import java.util.*;
public class UtilTree {public static void main(String[] a){TreeMap<Integer,String> m=new TreeMap<>();for(int i=0;i<9;i++)m.put(i,"v"+i);NavigableMap<Integer,String> v=m.subMap(2,true,7,false);System.out.println(v+" "+v.descendingMap()+" "+v.floorKey(5)+" "+v.higherKey(5));v.descendingMap().pollFirstEntry();v.put(3,"x");Iterator<Integer> it=v.navigableKeySet().iterator();it.next();it.remove();System.out.println(m+" "+v);TreeSet<Integer> s=new TreeSet<>(Arrays.asList(5,2,8,1,3));System.out.println(s.descendingSet()+" "+s.subSet(2,true,8,false)+" "+s.ceiling(4));s.descendingSet().pollFirst();System.out.println(s);TreeMap<Integer,Integer> n=new TreeMap<>();for(int x:new int[]{4,2,6,1,3,5,7})n.put(x,x);Iterator<Integer> j=n.subMap(1,true,7,true).keySet().iterator();while(j.hasNext())if(j.next()==4)j.remove();System.out.println(n);TreeMap<String,Integer> z=new TreeMap<>(Comparator.nullsFirst(Comparator.naturalOrder()));z.put(null,1);z.put("b",2);System.out.println(z.descendingMap()+" "+z.headMap("c",true));}}
